   708   * @flags: should be one of #gnutls_pkcs_encrypt_flags_t elements bitwise or'd
   709   *
   710   * This function will encrypt the given bag.
   711   *
   712   * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned,
   713   *   otherwise a negative error code is returned.
   714   **/
   715  int
   716  gnutls_pkcs12_bag_encrypt(gnutls_pkcs12_bag_t bag, const char *pass,
   717                            unsigned int flags)
   718  {
   719          int ret;
   720          ASN1_TYPE safe_cont = ASN1_TYPE_EMPTY;
   721          gnutls_datum_t der = { NULL, 0 };
   722          gnutls_datum_t enc = { NULL, 0 };
